`,solutionSql:"SELECT id, CASE WHEN p_id IS NULL THEN 'Root' WHEN id IN (SELECT p_id FROM tree WHERE p_id IS NOT NULL) THEN 'Inner' ELSE 'Leaf' END AS type FROM tree ORDER BY id;",expectedColumns:["id","type"],hints:["Remember to filter out NULLs when checking: WHEN id IN (SELECT p_id FROM tree WHERE p_id IS NOT NULL)"]},{id:"c6-sub-3",title:"Practice 3: Department Highest Salary (LeetCode 184)",difficulty:"Medium",source:"LeetCode",sourceId:"LeetCode 184",instructions:"Find employees who have the highest salary in each of the departments. Return Department, Employee, and Salary.",schemaSql:`
